528	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
529	  return new Promise((resolve) => {
530	    sftp.readFile(path, "utf8", (err, data) => resolve(err ? null : String(data)));
531	  });
532	}
