534	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
535	  return new Promise((resolve, reject) => {
536	    sftp.writeFile(path, content, { encoding: "utf8" }, (err) => (err ? reject(err) : resolve()));
537	  });
538	}
