/**
 * TEMPORARY live-verification harness for the 2026-09-30 mod-family coverage
 * pass — NOT committed (scratch). Drives the real worker/game-mods.ts code path
 * (gameModSync) against a real test server, exactly like the GAME_MOD_SYNC job
 * the dashboard enqueues, but without needing a customer session.
 *
 *   npx tsx scripts/_modverify-harness.ts install <serverId> <gameModId> [<gameModId>...]
 *   npx tsx scripts/_modverify-harness.ts remove  <serverId> <gameModId> [...]
 *   npx tsx scripts/_modverify-harness.ts status  <serverId>
 */
import { db } from "../lib/db";
import { gameModSync } from "../worker/game-mods";

async function main() {
  const [cmd, serverId, ...modIds] = process.argv.slice(2);
  if (!cmd || !serverId) throw new Error("usage: install|remove|status <serverId> [modIds...]");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { user: { select: { email: true } } } });
  if (!server) throw new Error("no such server");
  // Hard guard: only ever the internal e2e test account's servers.
  if (server.user.email !== "e2e-test@nxeon.local") throw new Error(`refusing: server belongs to ${server.user.email}`);

  if (cmd === "install" || cmd === "remove") {
    for (const modId of modIds) {
      const mod = await db.gameMod.findUnique({ where: { id: modId } });
      if (!mod) throw new Error(`no mod ${modId}`);
      if (cmd === "install") {
        await db.serverMod.upsert({
          where: { serverId_modId: { serverId, modId } },
          create: { serverId, modId, status: "INSTALLING", error: null },
          update: { status: "INSTALLING", error: null },
        });
      } else {
        await db.serverMod.update({ where: { serverId_modId: { serverId, modId } }, data: { status: "REMOVING" } });
      }
      console.log(`${cmd}: ${mod.gameFamily}/${mod.source}/${mod.sourceId} ${mod.name}`);
    }
    const t0 = Date.now();
    await gameModSync({ id: "harness", serverId, type: "GAME_MOD_SYNC" } as any);
    console.log(`gameModSync finished in ${Math.round((Date.now() - t0) / 1000)}s`);
  }
  const rows = await db.serverMod.findMany({ where: { serverId }, include: { mod: true } });
  for (const r of rows) console.log(`  ${r.status.padEnd(10)} ${r.mod.source}/${r.mod.sourceId} ${r.mod.name}${r.error ? `  ERROR: ${r.error}` : ""}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());

