/**
 * TEMPORARY (not committed): provision / delete a throwaway game server for the
 * 2026-09-30 mod-coverage live verification. Owned by the internal
 * e2e-test@nxeon.local account, isFree (no billing), pinned to a chosen node.
 *
 *   npx tsx scripts/_modverify-provision.ts create <family> <nodeName>
 *   npx tsx scripts/_modverify-provision.ts delete <serverId>
 *   npx tsx scripts/_modverify-provision.ts show <serverId>
 */
import { db } from "../lib/db";
import { serverRootPassword, connectionTarget } from "../lib/sftp";

async function main() {
  const [cmd, a, b] = process.argv.slice(2);
  if (cmd === "create") {
    const family = a;
    const node = await db.node.findFirst({ where: { name: b } });
    if (!node) throw new Error(`no node ${b}`);
