/** Unturned — `WorkshopDownloadConfig.json` (`{ Workshop: true, File_IDs: [...] }`),
 *  confirmed against Smartly Dressed Games' own official server-hosting docs.
 *  Written straight to disk, no container recreate needed — the dedicated
 *  server reads this file on ITS OWN next start.
 *
 *  FIXED 2026-09-30 — the path used to be hardcoded as
 *  `/opt/unturned/Servers/nxeon`, which was only right for fragsoc/unturned
 *  (prisma/seed-wave2-games.ts: `-v /opt/unturned:/config -e SERVER_ID=nxeon`).
 *  Production's live `unturned` OsTemplate has run imperialplugins/unturned
 *  since Wave 7 (read from the live DB, 2026-09-30):
 *  `-v /opt/unturned:/home/steam/Unturned/Servers -e SERVER_NAME='Nxeon Unturned'`,
 *  and that image's own init.sh launches `+secureserver/"$SERVER_NAME"`
 *  (github.com/ImperialPlugins/Unturned-Docker, init.sh) — so the server's
 *  directory is `/opt/unturned/<SERVER_NAME>` on the host, and the old path
 *  (`Servers/Servers/nxeon` from the game's point of view) was a file the
 *  server never reads: every Unturned Workshop install reported INSTALLED
 *  while nothing would ever load. The directory is now derived from the
 *  running container's own mount + env instead of assumed. */
async function unturnedServerDir(conn: Client): Promise<string | null> {
  const mounts = await execRemote(conn, `docker inspect unturned --format '{{range .Mounts}}{{.Source}}|{{.Destination}}{{"\\n"}}{{end}}'`);
  if (mounts.code !== 0) return null;
  const env = await readEnvMap(conn, "unturned");
  const lines = mounts.stdout.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  for (const l of lines) {
    const [src, dst] = l.split("|");
    if (!src || !dst) continue;
    // imperialplugins/unturned — host dir IS the game's Servers/ folder.
    if (/\/Servers\/?$/.test(dst)) {
      const name = env?.get("SERVER_NAME") || "server"; // the image's own Dockerfile default: ENV SERVER_NAME server
      if (name.includes("/") || name.includes("..")) return null;
      return `${src.replace(/\/$/, "")}/${name}`;
    }
    // fragsoc/unturned — whole config dir mounted, SERVER_ID picks the instance.
    if (dst === "/config") {
      const id = env?.get("SERVER_ID") || "nxeon";
      if (id.includes("/") || id.includes("..")) return null;
      return `${src.replace(/\/$/, "")}/Servers/${id}`;
    }
  }
  return null;
}

async function applyUnturnedWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
  return withSftp(server, async (conn, sftp) => {
    const dir = await unturnedServerDir(conn);
    if (!dir) return { ok: false, error: `Could not locate this Unturned server's own folder — is the server fully set up?` };
    await execRemote(conn, `mkdir -p '${shq(dir)}'`);
    const body = JSON.stringify({ Workshop: true, File_IDs: ids.map((id) => Number(id)) }, null, 2) + "\n";
    await sftpWrite(sftp, `${dir}/WorkshopDownloadConfig.json`, body);
    return { ok: true };
  });
}

