/**
 * TEMPORARY (not committed): run a shell command on a mod-coverage test server
 * over the same root-SSH path the worker uses, without ever printing the
 * password. Refuses anything not owned by e2e-test@nxeon.local.
 *
 *   npx tsx scripts/_modverify-exec.ts <serverId> '<command>'
 */
import { db } from "../lib/db";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { Client } from "ssh2";

async function main() {
  const [id, ...rest] = process.argv.slice(2);
  const cmd = rest.join(" ");
  const s = await db.server.findUnique({ where: { id }, include: { user: { select: { email: true } }, node: true, dedicatedIp: true } });
  if (!s) throw new Error("no such server");
  if (s.user.email !== "e2e-test@nxeon.local") throw new Error(`refusing: belongs to ${s.user.email}`);
  const t = connectionTarget(s as any);
  const pw = serverRootPassword(s as any);
  if (!t || !pw) throw new Error("no target/password");
  await new Promise<void>((resolve, reject) => {
    const c = new Client();
    c.on("ready", () => {
      c.exec(cmd, (err, stream) => {
        if (err) return reject(err);
        stream.on("close", (code: number) => { c.end(); process.exitCode = code ?? 0; resolve(); });
        stream.on("data", (d: Buffer) => process.stdout.write(d));
        stream.stderr.on("data", (d: Buffer) => process.stderr.write(d));
      });
    });
    c.on("error", reject);
    c.connect({ host: t.host, port: t.port, username: "root", password: pw, readyTimeout: 20000 });
  });
}
main().catch((e) => { console.error(e); process.exitCode = 1; }).finally(() => db.$disconnect());

