/**
 * Pure (no I/O, no Prisma) helpers for worker/game-mods.ts's 2026-09-30
 * family-coverage pass. Kept in their own module so test/*.test.ts can
 * exercise the exact code the worker runs without opening a database
 * connection or an SSH session — every function here is what decides WHAT
 * gets written to a customer's server, so it is the part worth pinning down
 * with tests.
 */

// ---------------------------------------------------------------------------
// Vintage Story — ModDB release selection
// ---------------------------------------------------------------------------

/** The subset of a ModDB `/api/mod/{id}` release we use (real field names,
 *  read live from mods.vintagestory.at 2026-09-30). */
export type VsRelease = {
  mainfile: string;
  filename: string;
  modidstr: string;
  modversion: string;
  tags: string[];
  created: string;
};

/**
 * Pick the release to install for a server running `gameVersion` (e.g.
 * "1.22.7"). Vintage Story mods are built against specific game versions and
 * the ModDB tags every release with the exact versions it supports — a
 * release for a different game version usually fails to load, so this never
 * "falls back" to an untagged newest release: no exact match means no
 * install, and the caller says so.
 *
 * Among matches it prefers stable releases (a `modversion` without a
 * pre-release suffix like "2.0.0-pre.8"), newest first; a pre-release is
 * only chosen when it is the ONLY build that supports this game version.
 */
export function pickVsRelease(releases: VsRelease[], gameVersion: string): VsRelease | null {
  const v = gameVersion.replace(/^v/i, "").trim();
  const matching = releases
    .filter((r) => Array.isArray(r.tags) && r.tags.includes(v) && !!r.mainfile)
    .sort((a, b) => (a.created < b.created ? 1 : a.created > b.created ? -1 : 0));
  const stable = matching.find((r) => !/-/.test(r.modversion));
  return stable ?? matching[0] ?? null;
}

/** Built-in "mods" every Vintage Story server already has — a dependency on
 *  one of these is satisfied by the game itself, never by the ModDB. */
export const VS_BUILTIN_MODIDS = new Set(["game", "survival", "creative"]);

/** File extension to keep for a ModDB mainfile (zip mods are the norm; the
 *  ModDB also hosts bare .dll / .cs code mods, which the server loads as-is). */
export function vsFileExt(filename: string): "zip" | "dll" | "cs" | null {
  const m = /\.(zip|dll|cs)$/i.exec(filename);
  return m ? (m[1].toLowerCase() as "zip" | "dll" | "cs") : null;
}

// ---------------------------------------------------------------------------
// Barotrauma — config_player.xml <regularpackages> management
// ---------------------------------------------------------------------------

export const BARO_PKG_PREFIX = "LocalMods/nxw-";

/**
 * Rewrite the `<regularpackages>` block of a Barotrauma `config_player.xml`
 * so it enables exactly `folders` (each `LocalMods/<folder>/filelist.xml`)
 * among the packages THIS platform manages (folder names starting `nxw-`),
 * leaving every package the customer added by hand untouched and in place.
 *
 * Returns null when the file has no `<contentpackages>` element at all —
 * the caller must not guess a structure the game didn't write.
 */
export function updateBarotraumaPackages(xml: string, folders: string[]): string | null {
  if (!/<contentpackages\b/i.test(xml)) return null;
  const managed = folders.map((f) => `    <package path="LocalMods/${f}/filelist.xml" enabled="true" />`);
  const regularRe = /<regularpackages\s*>([\s\S]*?)<\/regularpackages>/i;
  const selfClosingRe = /<regularpackages\s*\/>/i;
  if (regularRe.test(xml)) {
    return xml.replace(regularRe, (_all, inner: string) => {
      const kept = inner
        .split(/\r?\n/)
        .filter((l) => l.trim() && !l.includes(`path="${BARO_PKG_PREFIX}`));
      const body = [...kept, ...managed].join("\n");
      return `<regularpackages>\n${body}\n  </regularpackages>`;
    });
  }
  const block = `<regularpackages>\n${managed.join("\n")}\n  </regularpackages>`;
  if (selfClosingRe.test(xml)) return xml.replace(selfClosingRe, block);
  return xml.replace(/<\/contentpackages>/i, `  ${block}\n  </contentpackages>`);
}

// ---------------------------------------------------------------------------
// Garry's Mod — client auto-download list
// ---------------------------------------------------------------------------

/**
 * A server-side Lua autorun file that makes joining players download each
 * installed Workshop addon — `resource.AddWorkshop` is Garry's Mod's own,
 * documented API for exactly this (wiki.facepunch.com/gmod/resource.AddWorkshop).
 * Without it, a content addon the SERVER has mounted shows up to players as
 * missing textures / ERROR models, because the server never tells their
 * client to fetch it.
 */
export function gmodWorkshopLua(ids: string[]): string {
  const lines = [
    "-- Managed by Nxeon's mod installer: one resource.AddWorkshop per installed Workshop addon.",
    "-- Edits here are overwritten the next time mods are installed or removed from the dashboard.",
    ...ids.filter((id) => /^\d+$/.test(id)).map((id) => `resource.AddWorkshop("${id}")`),
  ];
  return lines.join("\n") + "\n";
}

// ---------------------------------------------------------------------------
// Killing Floor 2 — the image's own env var
// ---------------------------------------------------------------------------

/** rouhim/killing-floor-2-server's envini mapping (container-data/
 *  envini_mapping.ini, `expand = true`) turns this one comma-separated env
 *  var into one `ServerSubscribedWorkshopItems=<id>` line per id under
 *  `[OnlineSubsystemSteamworks.KFWorkshopSteamworks]` on every boot. */
export const KF2_WORKSHOP_ENV = "KF2_SERVER_SUBSCRIBED_WORKSHOP_ITEMS";

export function kf2WorkshopEnvValue(ids: string[]): string {
  return ids.filter((id) => /^\d+$/.test(id)).join(",");
}

// ---------------------------------------------------------------------------
// Shared
// ---------------------------------------------------------------------------

/** Only plain numeric Steam Workshop ids ever reach a shell command. */
export function isWorkshopId(id: string): boolean {
  return /^\d{1,20}$/.test(id);
}

