 * Returns null when the file has no `<contentpackages>` element at all —
 * the caller must not guess a structure the game didn't write.
 */
export function updateBarotraumaPackages(xml: string, folders: string[]): string | null {
  if (!/<contentpackages\b/i.test(xml)) return null;
  const managed = folders.map((f) => `    <package path="LocalMods/${f}/filelist.xml" enabled="true" />`);
  const regularRe = /<regularpackages\s*>([\s\S]*?)<\/regularpackages>/i;
  const selfClosingRe = /<regularpackages\s*\/>/i;
  if (regularRe.test(xml)) {
    return xml.replace(regularRe, (_all, inner: string) => {
      const kept = inner
        .split(/\r?\n/)
        .filter((l) => l.trim() && !l.includes(`path="${BARO_PKG_PREFIX}`));
      const body = [...kept, ...managed].join("\n");
      return `<regularpackages>\n${body}\n  </regularpackages>`;
    });
  }
  const block = `<regularpackages>\n${managed.join("\n")}\n  </regularpackages>`;
  if (selfClosingRe.test(xml)) return xml.replace(selfClosingRe, block);
  return xml.replace(/<\/contentpackages>/i, `  ${block}\n  </contentpackages>`);
}

