export function gmodWorkshopLua(ids: string[]): string {
  const lines = [
    "-- Managed by Nxeon's mod installer: one resource.AddWorkshop per installed Workshop addon.",
    "-- Edits here are overwritten the next time mods are installed or removed from the dashboard.",
    ...ids.filter((id) => /^\d+$/.test(id)).map((id) => `resource.AddWorkshop("${id}")`),
