// ===========================================================================
// 2026-09-30 family-coverage pass — more families, and new mod sources.
//
// Everything below was added by the survey-then-build pass documented in
// docs/DOCUMENTATION.md's 2026-09-30 entry (family-by-family table of what
// each dedicated server really supports). Each family here was wired only
// after its mechanism was confirmed against the production image's own
// source and, where noted, exercised against a real running test server.
// ===========================================================================

type ExtraSync = (server: SshServer, mod: ModRowFull, removing: boolean) => Promise<ModResult>;

/** Sources handled end-to-end by a family-specific installer below rather
 *  than by planTarget/resolveUrl/modDirShell (minecraft/rust/valheim) or by
 *  workshopSync (Steam Workshop). Keyed by `GameMod.source`. */
const EXTRA_SOURCE_SYNC: Record<string, ExtraSync> = {
  vintagestory_moddb: vintageStorySync,
};

/** Restart the game through its systemd unit (what worker/game-variant.ts's
 *  wrapDockerGameService creates at provision), falling back to docker for a
 *  container that predates that wrapper. */
async function restartGame(conn: Client, family: string, container: string): Promise<boolean> {
  const unit = await resolveUnit(conn, family);
  const r = await execRemote(conn, unit ? `systemctl restart '${shq(unit)}'` : `docker restart ${container}`);
  return r.code === 0;
}

// --- Vintage Story — official ModDB (mods.vintagestory.at) ------------------
//
// VERIFIED LIVE 2026-09-30 on a real test server (ich777/vintagestory, the
// production image):
//  - the image runs `VintagestoryServer --dataPath /vintagestory/data`, and
//    Nxeon mounts `/opt/vintagestory:/vintagestory`, so the user mod folder is
//    /opt/vintagestory/data/Mods on the VM (serverconfig.json's ModPaths is
//    ["Mods", "/vintagestory/data/Mods"]; `~/Mods` is the game's own built-in
//    DLLs and says "do_not_add_mods_here.txt");
//  - the server scans that folder on boot and logs
//    "Mods, sorted by dependency: game, creative, survival, <modid>…" to
//    data/Logs/server-main.log, which it archives and recreates on every start;
//  - "Game Version: v1.22.7 (Stable)" is the first thing that log records.
// The ModDB API is public and keyless (`/api/mod/{id}` returns every release
// with its CDN `mainfile` and the exact game versions it supports), so the
// VM downloads straight from the ModDB's CDN — nothing is mirrored by Nxeon.

const VS_ROOT = "/opt/vintagestory";
const VS_MODS = `${VS_ROOT}/data/Mods`;
const VS_LOG = `${VS_ROOT}/data/Logs/server-main.log`;

type VsModDetail = { modid: number; urlalias: string | null; name: string; releases: VsRelease[] };

async function fetchVsMod(idOrAlias: string): Promise<VsModDetail | null> {
  try {
    const res = await fetch(`https://mods.vintagestory.at/api/mod/${encodeURIComponent(idOrAlias)}`, {
      headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
    });
    if (!res.ok) return null;
    const body = (await res.json()) as { statuscode?: string; mod?: VsModDetail };
    return body.mod && Array.isArray(body.mod.releases) ? body.mod : null;
  } catch (e) {
    console.error(`[game-mods] ModDB lookup ${idOrAlias} failed`, e);
    return null;
  }
}

/** Python run ON THE VM (python3 ships with every Nxeon Ubuntu template):
 *  reads modinfo.json out of mod zips — Vintage Story's own manifest — so
 *  dependencies come from the mod itself, not a guess. VS parses that file
 *  leniently (case-insensitive keys, comments allowed), so this does too. */
const VS_MODINFO_PY = String.raw`
import sys, json, zipfile, re, os
def load(t):
    try: return json.loads(t)
    except Exception:
        t = re.sub(r'/\*.*?\*/', '', t, flags=re.S)
        t = re.sub(r'(^|[^:"])//[^\n]*', r'\1', t)
        t = re.sub(r',\s*([}\]])', r'\1', t)
        return json.loads(t)
def info_zip(p):
    try:
        with zipfile.ZipFile(p) as z:
            ns = sorted([n for n in z.namelist() if n.lower().rsplit('/',1)[-1] == 'modinfo.json'], key=lambda n: n.count('/'))
            if not ns: return None
            d = load(z.read(ns[0]).decode('utf-8-sig'))
    except Exception:
        return None
    d = {str(k).lower(): v for k, v in d.items()}
    mid = str(d.get('modid') or '').strip().lower() or re.sub(r'[^a-z0-9]', '', str(d.get('name') or '').lower())
    deps = d.get('dependencies') or {}
    return {'modid': mid, 'version': str(d.get('version') or ''), 'deps': {str(k).lower(): str(v) for k, v in deps.items()}}
if sys.argv[1] == 'one':
    print(json.dumps(info_zip(sys.argv[2])))
else:
    ids = []
    for f in sorted(os.listdir(sys.argv[2])):
        if f.lower().endswith('.zip'):
            i = info_zip(os.path.join(sys.argv[2], f))
            if i and i['modid']: ids.append(i['modid'])
    print(json.dumps(ids))
`;

async function vsGameVersion(conn: Client): Promise<string | null> {
  const r = await execRemote(
    conn,
    `v=$(grep -m1 -o 'Game Version: v[0-9A-Za-z.+-]*' '${VS_LOG}' 2>/dev/null | sed 's/^Game Version: v//'); ` +
      `[ -n "$v" ] || v=$(ls '${VS_ROOT}' 2>/dev/null | sed -n 's/^installed-//p' | head -1); echo "$v"`
  );
  const v = r.stdout.trim();
  return /^\d+\.\d+\.\d+/.test(v) ? v : null;
}

async function vsInspect(conn: Client, path: string): Promise<{ modid: string; version: string; deps: Record<string, string> } | null> {
  const r = await execRemote(conn, `python3 - one '${shq(path)}' <<'NXPY'\n${VS_MODINFO_PY}\nNXPY`);
  try {
    return JSON.parse(r.stdout.trim());
  } catch {
    return null;
  }
}

async function vsInstalledModIds(conn: Client): Promise<Set<string>> {
  const r = await execRemote(conn, `python3 - dir '${VS_MODS}' <<'NXPY'\n${VS_MODINFO_PY}\nNXPY`);
  try {
    return new Set((JSON.parse(r.stdout.trim()) as string[]).map((s) => s.toLowerCase()));
  } catch {
    return new Set();
  }
}

/** Download one ModDB file onto the VM (into `tmpDir`), returning its path. */
async function vsDownload(conn: Client, tmpDir: string, rel: VsRelease, name: string): Promise<string | null> {
  const ext = vsFileExt(rel.filename);
  if (!ext) return null;
  const dest = `${tmpDir}/${name}.${ext}`;
  const r = await execRemote(conn, `curl -fsSL --max-time 180 -o '${shq(dest)}' '${shq(rel.mainfile)}' && echo NXOK`);
  return /NXOK/.test(r.stdout) ? dest : null;
}

async function vintageStorySync(server: SshServer, mod: ModRowFull, removing: boolean): Promise<ModResult> {
  if (mod.gameFamily !== "vintagestory") return { ok: false, error: "This mod source only serves Vintage Story." };
  const safeSlug = mod.slug.replace(/[^a-z0-9_-]/gi, "");
  if (!safeSlug) return { ok: false, error: "This catalogue entry has no usable identifier." };

  return withSsh(server, async (conn) => {
    const dirCheck = await execRemote(conn, `[ -d '${VS_MODS}' ] && echo YES`);
    if (dirCheck.stdout.trim() !== "YES") {
      return { ok: false, error: "Couldn't find this server's Mods folder — is the server fully set up?" };
    }

    if (removing) {
      await execRemote(conn, `rm -f '${VS_MODS}'/nxeon-${safeSlug}.zip '${VS_MODS}'/nxeon-${safeSlug}.dll '${VS_MODS}'/nxeon-${safeSlug}.cs`);
      await restartGame(conn, "vintagestory", "vintagestory");
      return { ok: true };
    }

    const gameVersion = await vsGameVersion(conn);
    if (!gameVersion) return { ok: false, error: "Couldn't read this server's Vintage Story version — start it once, then try again." };
    const detail = await fetchVsMod(mod.sourceId ?? mod.slug);
    if (!detail) return { ok: false, error: "Couldn't reach this mod on the Vintage Story ModDB (it may have been removed)." };
    const rel = pickVsRelease(detail.releases, gameVersion);
    if (!rel) {
      return { ok: false, error: `${detail.name} has no release for Vintage Story ${gameVersion} yet — nothing was installed.` };
    }

    const tmpRes = await execRemote(conn, "mktemp -d");
    const tmp = tmpRes.stdout.trim();
    if (!tmp.startsWith("/tmp/")) return { ok: false, error: "Couldn't prepare a download folder on the server." };
    try {
      const mainPath = await vsDownload(conn, tmp, rel, `nxeon-${safeSlug}`);
      if (!mainPath) return { ok: false, error: "Download from the Vintage Story ModDB failed on the server." };

      // Dependencies, read from each mod's own modinfo.json, resolved against
      // what's already in the Mods folder, fetched from the ModDB by modid.
      // Bounded (depth + count) so a malformed or circular manifest can't loop.
      const present = await vsInstalledModIds(conn);
      const staged: string[] = [mainPath];
      const queue: { path: string; depth: number }[] = [{ path: mainPath, depth: 0 }];
      const seen = new Set<string>();
      const missing: string[] = [];
      while (queue.length) {
        const { path, depth } = queue.shift()!;
        if (!path.endsWith(".zip")) continue; // .dll/.cs code mods declare deps in code attributes, not modinfo.json
        const info = await vsInspect(conn, path);
        if (!info) continue;
        seen.add(info.modid);
        for (const dep of Object.keys(info.deps)) {
          if (VS_BUILTIN_MODIDS.has(dep) || present.has(dep) || seen.has(dep)) continue;
          seen.add(dep);
          if (depth >= 3 || staged.length >= 12) { missing.push(dep); continue; }
          const d = await fetchVsMod(dep);
          const dRel = d ? pickVsRelease(d.releases, gameVersion) : null;
          const dPath = dRel ? await vsDownload(conn, tmp, dRel, `nxeon-dep-${dep.replace(/[^a-z0-9_-]/g, "")}`) : null;
          if (!dPath) { missing.push(dep); continue; }
          staged.push(dPath);
          queue.push({ path: dPath, depth: depth + 1 });
        }
      }
      if (missing.length) {
        return {
          ok: false,
          error: `${detail.name} needs ${missing.join(", ")}, which couldn't be found on the ModDB for Vintage Story ${gameVersion} — nothing was installed.`,
        };
      }

      // Everything resolved: move into place (deterministic names so removal
      // is a plain rm), owned like the folder the game itself created.
      const moves = staged.map((p) => `mv -f '${shq(p)}' '${VS_MODS}/' && chown --reference='${VS_MODS}' '${VS_MODS}/${shq(p.split("/").pop()!)}'`).join(" && ");
      const mv = await execRemote(conn, `${moves} && echo NXOK`);
      if (!/NXOK/.test(mv.stdout)) return { ok: false, error: "Couldn't move the downloaded mod into the Mods folder." };

      // Restart and read the fresh log: VS archives server-main.log and starts
      // a new file on every boot, so wait for a NEW file (different inode) that
      // has reached its mod list, then check this mod is in it.
      const ino = (await execRemote(conn, `stat -c %i '${VS_LOG}' 2>/dev/null`)).stdout.trim();
      if (!(await restartGame(conn, "vintagestory", "vintagestory"))) {
        return { ok: false, error: "The mod was placed, but the server didn't restart — restart it from the dashboard to load it." };
      }
      const mainInfo = mainPath.endsWith(".zip") ? rel.modidstr.toLowerCase() : null;
      const probe = await execRemote(
        conn,
        `for i in $(seq 1 60); do n=$(stat -c %i '${VS_LOG}' 2>/dev/null); ` +
          `if [ -n "$n" ] && [ "$n" != '${shq(ino)}' ] && grep -q 'Mods, sorted by dependency' '${VS_LOG}'; then grep -m1 'Mods, sorted by dependency' '${VS_LOG}'; exit 0; fi; sleep 2; done; echo NXTIMEOUT`
      );
      const line = probe.stdout.trim();
      if (mainInfo && line && !/NXTIMEOUT/.test(line)) {
        const loaded = line.replace(/^.*Mods, sorted by dependency:\s*/, "").split(/,\s*/).map((s) => s.trim().toLowerCase());
        if (!loaded.includes(mainInfo)) {
          return { ok: false, error: `The server restarted but did not load ${detail.name} — check the server log for the reason.` };
        }
      }
      return { ok: true, version: rel.modversion };
    } finally {
      await execRemote(conn, `rm -rf '${shq(tmp)}'`);
    }
  });
}
