// --- Container recreate that reproduces the RUNNING container ---------------
//
// The older per-family env writers above (ark/dst/squad/soulmask) each carry
// a hand-copied `runFlags` string that has to be kept in sync with the
// family's OsTemplate setupScript by hand. For the families added in this
// pass the flags are instead READ BACK from the live container (`docker
// inspect`): its real port bindings, bind mounts, stop timeout, hostname and
// any entrypoint/command override — so a setupScript change, or a customer
// setting applied at provision time, can't be silently dropped by a mod
// install. Anything this can't faithfully reproduce (a multi-part entrypoint
// override) is refused rather than approximated.

type InspectJson = {
  Config?: { Image?: string; Hostname?: string; StopTimeout?: number | null; Entrypoint?: string[] | null; Cmd?: string[] | null };
  HostConfig?: { Binds?: string[] | null; PortBindings?: Record<string, { HostIp?: string; HostPort?: string }[] | null> | null };
};

async function inspectRunSpec(conn: Client, container: string): Promise<{ flags: string; image: string } | { error: string }> {
  const r = await execRemote(conn, `docker inspect ${container} --format '{{json .}}'`);
  if (r.code !== 0) return { error: `Could not find the "${container}" container — is the server fully set up?` };
  let j: InspectJson;
  try {
    j = JSON.parse(r.stdout.trim());
  } catch {
    return { error: "Could not read the game container's configuration." };
  }
  const image = j.Config?.Image;
  if (!image || !/^[\w./:@-]+$/.test(image)) return { error: "Could not determine the game container's image." };

  const flags: string[] = [];
  for (const [cport, binds] of Object.entries(j.HostConfig?.PortBindings ?? {})) {
    if (!/^\d+\/(tcp|udp)$/.test(cport)) continue;
    for (const b of binds ?? []) {
      const hp = b.HostPort ?? "";
      if (!/^\d+$/.test(hp)) continue;
      const ip = b.HostIp && /^[\d.]+$/.test(b.HostIp) && b.HostIp !== "0.0.0.0" ? `${b.HostIp}:` : "";
      flags.push(`-p ${ip}${hp}:${cport}`);
    }
  }
  for (const bind of j.HostConfig?.Binds ?? []) flags.push(`-v '${shq(bind)}'`);
  if (typeof j.Config?.StopTimeout === "number") flags.push(`--stop-timeout ${j.Config.StopTimeout}`);
  if (j.Config?.Hostname === container) flags.push(`--hostname ${container}`);

  const imgRes = await execRemote(conn, `docker image inspect '${shq(image)}' --format '{{json .Config}}'`);
  let img: { Entrypoint?: string[] | null; Cmd?: string[] | null } = {};
  try {
    img = JSON.parse(imgRes.stdout.trim());
  } catch {
    /* image metadata unavailable — treat as no override information */
  }
  const same = (a: unknown, b: unknown) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);
  if (!same(j.Config?.Entrypoint, img.Entrypoint)) {
    const ep = j.Config?.Entrypoint ?? [];
    if (ep.length !== 1) return { error: "This server's container uses a custom entrypoint that can't be safely reproduced — nothing was changed." };
    flags.push(`--entrypoint '${shq(ep[0])}'`);
  }
  const args = !same(j.Config?.Cmd, img.Cmd) && j.Config?.Cmd?.length ? j.Config.Cmd.map((a) => `'${shq(a)}'`).join(" ") : "";
  return { flags: flags.join(" "), image: args ? `${image} ${args}` : image };
}

/** Set (or clear, when `value` is "") one env var on a family's container and
 *  recreate it with everything else exactly as it was. */
async function setContainerEnv(
  server: SshServer,
  family: string,
  container: string,
  key: string,
  value: string
): Promise<ModResult> {
  return withSftp(server, async (conn, sftp) => {
    const envMap = await readEnvMap(conn, container);
    if (!envMap) return { ok: false, error: `Could not find the "${container}" container — is the server fully set up?` };
    const spec = await inspectRunSpec(conn, container);
    if ("error" in spec) return { ok: false, error: spec.error };
    if (value) envMap.set(key, value);
    else envMap.delete(key);
    const envPath = `/root/${container}.env`;
    await writeContainerEnvFile(conn, sftp, envPath, envMap);
    const res = await recreateContainer(conn, { family, container, runFlags: `${spec.flags} --env-file ${envPath}`, image: spec.image });
    return res.ok ? { ok: true } : { ok: false, error: res.note };
  });
}
EOF
timeout 600 npx tsc --noEmit 2>&1 | tail -5; echo EXIT

