// --- Steam Workshop: fetch one item with the game container's OWN steamcmd ---
//
// For families whose dedicated server does not download Workshop content by
// itself, the item is fetched the way the existing L4D2/Empyrion/PZ paths do
// it: Valve's own `steamcmd`, run INSIDE the customer's own game container
// (every image below ships one), anonymously, into a staging folder on one
// of the container's bind mounts so the host can see the result. Nothing is
// downloaded to, or served from, Nxeon's own infrastructure. Anonymous
// workshop_download_item was confirmed to work for each of these appids by a
// real run on a test VM (2026-09-30): 602960 (Barotrauma), 1169040
// (Necesse), 4000 (Garry's Mod), 440900 (Conan), 544550 (Stationeers).

async function fetchWorkshopItem(
  conn: Client,
  o: { container: string; user?: string; steamcmd: string; appid: number; id: string; stageInContainer: string; stageOnHost: string }
): Promise<{ hostPath: string } | { error: string }> {
  if (!isWorkshopId(o.id)) return { error: "Not a valid Steam Workshop id." };
  await execRemote(conn, `mkdir -p '${shq(o.stageOnHost)}' && chmod 777 '${shq(o.stageOnHost)}'`);
  const run = await execRemote(
    conn,
    `docker exec ${o.user ? `-u ${o.user} ` : ""}${o.container} ${o.steamcmd} +force_install_dir '${shq(o.stageInContainer)}' ` +
      `+login anonymous +workshop_download_item ${o.appid} ${o.id} +quit 2>&1 | tr -d '\\r' | grep -E 'Success\\. Downloaded item|ERROR' | tail -2`
  );
  const hostPath = `${o.stageOnHost}/steamapps/workshop/content/${o.appid}/${o.id}`;
  const exists = await execRemote(conn, `[ -d '${shq(hostPath)}' ] && [ -n "$(ls -A '${shq(hostPath)}')" ] && echo YES`);
  if (exists.stdout.trim() !== "YES") {
    const why = run.stdout.trim().split(/\r?\n/).pop() ?? "";
    return { error: `Steam Workshop item ${o.id} could not be downloaded${/ERROR/.test(why) ? ` (${why.replace(/^.*ERROR!?\s*/, "")})` : ""} — it may be private, removed, or not for this game.` };
  }
  return { hostPath };
}

// --- Garry's Mod — Steam Workshop addons, placed as .gma --------------------
//
// ghcr.io/ich777/steamcmd:garrysmod (github.com/ich777/docker-steamcmd-server,
// `garrysmod` branch): serverfiles at /serverdata/serverfiles (= host
// /opt/gmod), steamcmd at /serverdata/steamcmd/steamcmd.sh (inside the
// container only), server runs as user `steam`. Garry's Mod mounts any .gma
// placed in garrysmod/addons/ at startup, and `resource.AddWorkshop` (its own
// documented API) makes joining clients fetch the same addon from Steam.
// `+host_workshop_collection` was considered and rejected: it only takes a
// COLLECTION id, and the catalogue is individual addons.
const GMOD_ROOT = "/opt/gmod/garrysmod";

async function applyGmodWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
  const wanted = ids.filter(isWorkshopId);
  return withSftp(server, async (conn, sftp) => {
    const root = await execRemote(conn, `[ -d '${GMOD_ROOT}' ] && echo YES`);
    if (root.stdout.trim() !== "YES") return { ok: false, error: "Couldn't find this server's garrysmod folder — is the server fully set up?" };
    await execRemote(conn, `mkdir -p '${GMOD_ROOT}/addons' '${GMOD_ROOT}/lua/autorun/server'`);
    for (const id of wanted) {
      const have = await execRemote(conn, `[ -s '${GMOD_ROOT}/addons/nxw-${id}.gma' ] && echo YES`);
