// --- Necesse — Steam Workshop mods, placed as .jar -------------------------
//
// andreasgl4ser/necesse-server (github.com/andreas-glaser/necesse-docker-
// server): the game's data dir /home/necesse/.config/Necesse is the one bind
// mount (= host /opt/necesse); steamcmd lives in the image at
// /steamapps/steamcmd.sh, owned by the `necesse` user the server runs as.
// A Necesse Workshop item is a single mod .jar (confirmed by a real anonymous
// download: 3445509102 → RaceMod-0.33.1-0.1.26.jar). The server loads every
// .jar in <data dir>/mods at startup — see the live-verification note in
// docs/DOCUMENTATION.md's 2026-09-30 entry for how this was confirmed.
const NECESSE_MODS = "/opt/necesse/mods";

async function applyNecesseWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
  const wanted = ids.filter(isWorkshopId);
  return withSsh(server, async (conn) => {
    const root = await execRemote(conn, `[ -d /opt/necesse ] && echo YES`);
    if (root.stdout.trim() !== "YES") return { ok: false, error: "Couldn't find this server's Necesse folder — is the server fully set up?" };
    await execRemote(conn, `mkdir -p '${NECESSE_MODS}'`);
    for (const id of wanted) {
      const have = await execRemote(conn, `ls '${NECESSE_MODS}'/nxw-${id}-*.jar >/dev/null 2>&1 && echo YES`);
      if (have.stdout.trim() === "YES") continue;
      const got = await fetchWorkshopItem(conn, {
        container: "necesse",
        user: "necesse",
        steamcmd: "/steamapps/steamcmd.sh",
        appid: WORKSHOP_APPID.necesse,
        id,
        stageInContainer: "/home/necesse/.config/Necesse/.nxw-workshop",
        stageOnHost: "/opt/necesse/.nxw-workshop",
      });
      if ("error" in got) return { ok: false, error: got.error };
      const place = await execRemote(
        conn,
        `j=$(find '${shq(got.hostPath)}' -maxdepth 2 -type f -iname '*.jar' | head -1); ` +
          `[ -n "$j" ] && cp -f "$j" '${NECESSE_MODS}'/nxw-${id}-"$(basename "$j" | tr -cd 'A-Za-z0-9._-')" && echo NXOK || echo NXBAD`
      );
      if (!/NXOK/.test(place.stdout)) return { ok: false, error: `Steam Workshop item ${id} downloaded, but it contains no Necesse mod .jar.` };
    }
    const present = await execRemote(conn, `ls '${NECESSE_MODS}' 2>/dev/null | sed -n 's/^nxw-\\([0-9]*\\)-.*\\.jar$/\\1/p' | sort -u`);
    for (const id of present.stdout.split(/\r?\n/).map((s) => s.trim()).filter(Boolean)) {
      if (!wanted.includes(id)) await execRemote(conn, `rm -f '${NECESSE_MODS}'/nxw-${id}-*.jar`);
    }
    await execRemote(conn, `rm -rf /opt/necesse/.nxw-workshop; chown -R --reference=/opt/necesse '${NECESSE_MODS}' 2>/dev/null; true`);
    if (!(await restartGame(conn, "necesse", "necesse"))) {
      return { ok: false, error: "The mod was placed, but the server didn't restart — restart it from the dashboard to load it." };
    }
    return { ok: true };
  });
}
EOF
