/**
 * Bulk-import the real Arma Reforger Workshop catalogue into `GameMod`
 * (gameFamily "armareforger", source "reforger_workshop") — the 2026-09-30
 * family-coverage pass's new mod source. Same shape/safety rails as the other
 * importers in this folder (read scripts/import-modio-catalog.ts first):
 * dry-run by default, `--apply` to write, scripts/db-target-guard.ts enforced,
 * idempotent upsert matched on the real immutable id.
 *
 * SOURCE — Bohemia Interactive's own Reforger Workshop
 * (https://reforger.armaplatform.com/workshop), NOT Steam: Arma Reforger's
 * dedicated server downloads mods from Bohemia's own backend by 16-hex-digit
 * GUID (see worker/game-mods.ts's reforgerSync for the install mechanism).
 * There is no documented public REST API; the Workshop website is a Next.js
 * app that server-renders each listing page with its data embedded as JSON
 * in `<script id="__NEXT_DATA__">` (`props.pageProps.assets = { count, rows }`
 * — checked live 2026-09-30: 50,106 assets, rows carry id/name/type/summary/
 * subscriberCount/currentVersionNumber/currentVersionSize/previews/tags/author/
 * dependencyTree). robots.txt is `User-agent: * / Allow: /` (checked live), so
 * reading those public pages is permitted; this script still paces itself
 * (one page per REQUEST_INTERVAL_MS) and reads only the listing pages — never
 * a mod file. The file itself is fetched by the customer's own game server at
 * install time, from Bohemia, exactly as a player-run server would.
 *
 * WHAT IS IMPORTED: `type === "addon"` rows (scenarios are a different kind of
 * asset — activating one means changing the server's scenarioId, which the
 * install mechanism does not do), not blocked/private/unlisted, with at least
 * MIN_SUBSCRIBERS subscribers, in the Workshop's own popularity order, capped
 * at --max (default 1000).
 *
 * FIELD NOTES — every value comes from the listing row, nothing is invented:
 *   - popularity = subscriberCount (the Workshop's own popularity signal);
 *     `downloads` stays null — the listing exposes no download count.
 *   - fileBytes = currentVersionSize; gameVersions = [dependencyTree.gameVersion]
 *     (the game build the current version targets) when present.
 *   - iconUrl = the first preview's smallest real JPEG thumbnail.
 *   - category = the first of the author's own tags, title-cased; "Addon" when
 *     there are none. license = null (the Workshop publishes none).
 *
 *   NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-reforger-workshop-catalog.ts [--apply] [--max=1000] [--min-subscribers=500]
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("import-reforger-workshop-catalog.ts");

import { db } from "../lib/db";

const FAMILY = "armareforger";
const SOURCE = "reforger_workshop";
const BASE = "https://reforger.armaplatform.com/workshop";
const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
const REQUEST_INTERVAL_MS = 1500;

type Row = {
  id: string;
  name: string;
  type: string;
  summary?: string | null;
  unlisted?: boolean;
  private?: boolean;
  blocked?: boolean;
  subscriberCount?: number;
  currentVersionNumber?: string;
  currentVersionSize?: number;
  previews?: { url?: string; thumbnails?: Record<string, { url: string; width: number }[]> }[];
  tags?: { name: string }[];
  author?: { username?: string } | null;
  dependencyTree?: { gameVersion?: string; dependencies?: unknown[] } | null;
};

function parseArgs(argv: string[]) {
  const get = (n: string) => argv.find((a) => a.startsWith(`--${n}=`))?.split("=")[1];
  return {
    apply: argv.includes("--apply"),
    max: Number(get("max") ?? 1000),
    minSubscribers: Number(get("min-subscribers") ?? 500),
  };
}

async function fetchPage(page: number): Promise<{ count: number; rows: Row[] }> {
  const res = await fetch(`${BASE}?sort=popularity&page=${page}`, { headers: { "User-Agent": UA } });
  if (!res.ok) throw new Error(`workshop page ${page}: HTTP ${res.status}`);
  const html = await res.text();
  const m = /<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/.exec(html);
  if (!m) throw new Error(`workshop page ${page}: no __NEXT_DATA__ (site layout changed?)`);
  const data = JSON.parse(m[1]);
  const assets = data?.props?.pageProps?.assets;
  if (!assets || !Array.isArray(assets.rows)) throw new Error(`workshop page ${page}: no assets.rows`);
  return { count: Number(assets.count ?? 0), rows: assets.rows as Row[] };
}

function slugify(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 70) || "mod";
}

function iconFor(r: Row): string | null {
  const p = r.previews?.[0];
  const thumbs = p?.thumbnails?.["image/jpeg"] ?? [];
  const smallest = [...thumbs].sort((a, b) => a.width - b.width)[0];
  return smallest?.url ?? p?.url ?? null;
}

function categoryFor(r: Row): string {
  const t = r.tags?.[0]?.name?.trim();
  if (!t) return "Addon";
  return t.charAt(0).toUpperCase() + t.slice(1).toLowerCase();
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  console.log(`Reforger Workshop import — ${args.apply ? "APPLY" : "DRY RUN"} max=${args.max} minSubscribers=${args.minSubscribers}`);

  const existing = await db.gameMod.findMany({ where: { gameFamily: FAMILY }, select: { id: true, slug: true, source: true, sourceId: true } });
  const bySourceId = new Map(existing.filter((e) => e.source === SOURCE && e.sourceId).map((e) => [e.sourceId as string, e]));
  const usedSlugs = new Set(existing.map((e) => e.slug));

  let page = 1;
  let kept = 0, created = 0, updated = 0, skipped = 0, failed = 0, total = 0;
  let stop = false;
  while (!stop && kept < args.max) {
    const { count, rows } = await fetchPage(page);
    total = count;
    if (rows.length === 0) break;
    for (const r of rows) {
      if (kept >= args.max) break;
      if (!/^[0-9A-F]{16}$/i.test(r.id) || r.type !== "addon" || r.blocked || r.private || r.unlisted) { skipped++; continue; }
      if ((r.subscriberCount ?? 0) < args.minSubscribers) { stop = true; break; } // popularity-ordered: everything after is below the floor too
      kept++;
      const prior = bySourceId.get(r.id);
      let slug = prior?.slug;
      if (!slug) {
        const base = slugify(r.name);
        slug = base;
        for (let i = 2; usedSlugs.has(slug); i++) slug = `${base}-${i}`;
        usedSlugs.add(slug);
      }
      const data = {
        name: r.name,
        category: categoryFor(r),
        description: r.summary?.trim() || null,
        iconUrl: iconFor(r),
        url: `${BASE}/${r.id}`,
        popularity: r.subscriberCount ?? 0,
        downloads: null,
        fileBytes: typeof r.currentVersionSize === "number" ? r.currentVersionSize : null,
        gameVersions: r.dependencyTree?.gameVersion ? [r.dependencyTree.gameVersion] : [],
        dependencyCount: Array.isArray(r.dependencyTree?.dependencies) ? r.dependencyTree!.dependencies!.length : 0,
        authorName: r.author?.username ?? null,
        license: null,
        source: SOURCE,
        sourceId: r.id.toUpperCase(),
        active: true,
        verifiedAt: new Date(),
        upstreamOk: true,
        upstreamNote: null,
      };
      if (!args.apply) {
        if (kept <= 5) console.log(`  [dry] ${r.id} ${r.name} subs=${r.subscriberCount} size=${r.currentVersionSize} slug=${slug}`);
        continue;
      }
      try {
        if (prior) {
          await db.gameMod.update({ where: { id: prior.id }, data, select: { id: true } });
          updated++;
        } else {
          await db.gameMod.create({ data: { gameFamily: FAMILY, slug, ...data }, select: { id: true } });
          created++;
        }
      } catch (e) {
        failed++;
        console.error(`  [db] ${r.id} ${r.name}: ${e instanceof Error ? e.message : e}`);
      }
    }
    if (page % 10 === 0) console.log(`  page=${page} kept=${kept} created=${created} updated=${updated} skipped=${skipped} failed=${failed}`);
    page++;
    await new Promise((res) => setTimeout(res, REQUEST_INTERVAL_MS));
  }
  console.log(`\nDONE (${args.apply ? "APPLIED" : "DRY RUN — nothing written"}): workshop total=${total} pages=${page - 1} kept=${kept} created=${created} updated=${updated} skipped=${skipped} failed=${failed}`);
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

