/**
 * TEMPORARY (not committed): install ANOTHER family's game container on a
 * mod-coverage test VM using that family's exact production provisioning
 * script — the live OsTemplate.setupScript run through the same
 * buildGameSetupScript() the worker's PROVISION uses (docker create + the
 * generated systemd unit named after the family's first serviceHint). Only the
 * leading `curl https://get.docker.com | sh &&` is dropped, since Docker is
 * already installed on the VM. Refuses anything not owned by e2e-test@nxeon.local.
 *
 *   npx tsx scripts/_modverify-gameinstall.ts <serverId> <family> [--print]
 */
import { db } from "../lib/db";
import { buildGameSetupScript } from "../worker/game-variant";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { Client } from "ssh2";

async function main() {
  const [id, family, flag] = process.argv.slice(2);
  const s = await db.server.findUnique({ where: { id }, include: { user: { select: { email: true } }, node: true, dedicatedIp: true } });
  if (!s || s.user.email !== "e2e-test@nxeon.local") throw new Error("refusing: not an e2e-test server");
  const tpl = await db.osTemplate.findFirst({ where: { family, setupScript: { not: null } } });
  if (!tpl?.setupScript) throw new Error(`no OsTemplate for ${family}`);
  let script = buildGameSetupScript({ osTemplate: { setupScript: tpl.setupScript, family: tpl.family }, gameVariant: null, gameConfig: null });
  if (!script) throw new Error("no script");
  script = script.replace(/^curl -fsSL https:\/\/get\.docker\.com \| sh && /, "");
  if (flag === "--print") {
    console.log(script);
    return;
  }
  const t = connectionTarget(s as any);
  const pw = serverRootPassword(s as any);
  if (!t || !pw) throw new Error("no target");
  await new Promise<void>((resolve, reject) => {
    const c = new Client();
    c.on("ready", () => {
      c.exec(`bash -s <<'NXSETUP'\nset -e\n${script}\nNXSETUP`, (err, stream) => {
        if (err) return reject(err);
        stream.on("close", (code: number) => { c.end(); process.exitCode = code ?? 0; resolve(); });
        stream.on("data", (d: Buffer) => process.stdout.write(d));
        stream.stderr.on("data", (d: Buffer) => process.stderr.write(d));
      });
    });
    c.on("error", reject);
    c.connect({ host: t.host, port: t.port, username: "root", password: pw, readyTimeout: 20000 });
  });
}
main().catch((e) => { console.error(e); process.exitCode = 1; }).finally(() => db.$disconnect());

