export type FicsitVersion = {
  version: string;
  stability?: string | null;
  game_version?: string | null;
  targets: { targetName: string; link: string; size?: number | null }[];
  dependencies: { mod_reference: string; condition: string; optional: boolean }[];
};

/**
 * Choose which ficsit.app version of a mod to put on a Linux dedicated
 * server: it must ship a `LinuxServer` build target (not every mod does —
 * docs.ficsit.app says so and the API lists targets per version), satisfy
 * the dependency `condition` that pulled it in (null for the mod the
 * customer picked), and not be ruled out by its `game_version` against the
 * server's build. Newest first (the API's own created_at-desc order is
 * preserved by the caller), release builds preferred over beta/alpha.
 */
export function pickFicsitVersion(versions: FicsitVersion[], condition: string | null, serverCL: number | null): FicsitVersion | null {
  const ok = versions.filter(
    (v) =>
      v.targets.some((t) => t.targetName === "LinuxServer") &&
      (!condition || satisfiesSemver(v.version, condition)) &&
      gameCLSatisfies(serverCL, v.game_version) !== false
  );
  return ok.find((v) => (v.stability ?? "release") === "release") ?? ok[0] ?? null;
}
