cat >> worker/game-mods.ts <<'EOF'

// --- Satisfactory — ficsit.app (the Satisfactory Mod Repository) -----------
//
// New mod source for this pass. ficsit.app is the game's community mod
// repository (the one Satisfactory Mod Manager itself uses); its GraphQL API
// (api.ficsit.app/v2/query) and file downloads (api.ficsit.app/v1/version/
// <id>/<target>/download → storage.ficsit.app) are public and keyless —
// checked live 2026-09-30. Every version lists its build targets; only
// `LinuxServer` builds are installable on Nxeon's Linux server
// (wolveix/satisfactory-server). Mods load through SML (Satisfactory Mod
// Loader, itself a mod — mod_reference "SML"), which every mod declares as a
// dependency, so the ordinary dependency walk installs it too. Each mod goes
// in FactoryGame/Mods/<mod_reference>/ (the .smod archive is a zip of that
// folder's contents), which is where SML/SMM look for it. The server's own
// install root is /config/gamefiles in the container = host
// /opt/satisfactory/gamefiles (wolveix run.sh: `+force_install_dir
// /config/gamefiles`).

const SF_ROOT = "/opt/satisfactory/gamefiles";
const SF_MODS = `${SF_ROOT}/FactoryGame/Mods`;
const FICSIT_API = "https://api.ficsit.app";

async function ficsitMod(ref: string): Promise<{ name: string; versions: FicsitVersion[] } | null> {
  const query = `query($ref: ModReference!) { getModByReference(modReference: $ref) { name versions(filter: { limit: 60, order_by: created_at, order: desc }) { version stability game_version targets { targetName link size } dependencies { mod_reference condition optional } } } }`;
  try {
    const res = await fetch(`${FICSIT_API}/v2/query`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "User-Agent": "Nxeon/1.0 (mod-manager)" },
      body: JSON.stringify({ query, variables: { ref } }),
    });
    if (!res.ok) return null;
    const body = (await res.json()) as { data?: { getModByReference?: { name: string; versions: FicsitVersion[] } | null } };
    return body.data?.getModByReference ?? null;
  } catch (e) {
    console.error(`[game-mods] ficsit lookup ${ref} failed`, e);
    return null;
  }
}

/** The server's build changelist, read from its own log (UE writes
 *  "Build: ++FactoryGame+rel-main-…-CL-<n>" / "Net CL: <n>" at startup). */
async function satisfactoryCL(conn: Client): Promise<number | null> {
  const r = await execRemote(
    conn,
    `f=$(ls -t '${SF_ROOT}'/FactoryGame/Saved/Logs/FactoryGame*.log 2>/dev/null | head -1); [ -n "$f" ] && grep -m1 -oE '(Net CL: [0-9]+|-CL-[0-9]+)' "$f" | grep -oE '[0-9]+$'`
  );
  const n = Number(r.stdout.trim());
  return Number.isFinite(n) && n > 0 ? n : null;
}

async function satisfactorySync(server: SshServer, mod: ModRowFull, removing: boolean): Promise<ModResult> {
  if (mod.gameFamily !== "satisfactory") return { ok: false, error: "This mod source only serves Satisfactory." };
  const mainRef = mod.sourceId ?? "";
  if (!/^[A-Za-z0-9_]{2,64}$/.test(mainRef)) return { ok: false, error: "This catalogue entry has no valid mod reference." };

  return withSsh(server, async (conn) => {
    const root = await execRemote(conn, `[ -d '${SF_ROOT}/FactoryGame' ] && echo YES`);
    if (root.stdout.trim() !== "YES") return { ok: false, error: "Couldn't find this server's game files — is the server fully set up?" };

    if (removing) {
      await execRemote(conn, `rm -rf '${SF_MODS}/${mainRef}'`);
      await restartGame(conn, "satisfactory", "satisfactory");
      return { ok: true };
    }

    // Resolve the full dependency closure first; download nothing until
    // every piece has a compatible LinuxServer build.
    const cl = await satisfactoryCL(conn);
    const chosen = new Map<string, FicsitVersion>();
    const queue: { ref: string; cond: string | null }[] = [{ ref: mainRef, cond: null }];
    while (queue.length) {
      const { ref, cond } = queue.shift()!;
      if (!/^[A-Za-z0-9_]{2,64}$/.test(ref)) return { ok: false, error: `A dependency has an invalid reference (${ref}).` };
      const have = chosen.get(ref);
      if (have) {
        if (cond && !satisfiesSemver(have.version, cond)) {
          return { ok: false, error: `Mods need incompatible versions of ${ref} (${have.version} vs ${cond}) — nothing was installed.` };
        }
        continue;
      }
      if (chosen.size >= 25) return { ok: false, error: "This mod pulls in too many dependencies to install automatically." };
      const info = await ficsitMod(ref);
      if (!info) return { ok: false, error: `Couldn't find ${ref} on ficsit.app — nothing was installed.` };
      const pick = pickFicsitVersion(info.versions, cond, cl);
      if (!pick) {
        return {
          ok: false,
          error: `${info.name} has no Linux dedicated-server build${cond ? ` matching ${cond}` : ""}${cl ? ` for this game build (CL ${cl})` : ""} — nothing was installed.`,
        };
      }
      chosen.set(ref, pick);
      for (const d of pick.dependencies) if (!d.optional) queue.push({ ref: d.mod_reference, cond: d.condition });
    }

    const tmp = (await execRemote(conn, "mktemp -d")).stdout.trim();
    if (!tmp.startsWith("/tmp/")) return { ok: false, error: "Couldn't prepare a download folder on the server." };
    try {
      await execRemote(conn, `mkdir -p '${SF_MODS}'`);
      for (const [ref, v] of chosen) {
        const link = v.targets.find((t) => t.targetName === "LinuxServer")!.link;
        if (!/^\/v1\/version\/[A-Za-z0-9]+\/LinuxServer\/download$/.test(link)) return { ok: false, error: `Unexpected download link for ${ref}.` };
        const r = await execRemote(
          conn,
          `set -e; f='${tmp}/${ref}.smod'; curl -fsSL --max-time 180 -o "$f" '${FICSIT_API}${link}'; ` +
            `rm -rf '${SF_MODS}/${ref}.nxnew'; mkdir -p '${SF_MODS}/${ref}.nxnew'; unzip -oq "$f" -d '${SF_MODS}/${ref}.nxnew'; ` +
            `[ -f '${SF_MODS}/${ref}.nxnew/${ref}.uplugin' ]; rm -rf '${SF_MODS}/${ref}'; mv '${SF_MODS}/${ref}.nxnew' '${SF_MODS}/${ref}'; echo NXOK`
        );
        if (!/NXOK/.test(r.stdout)) {
          await execRemote(conn, `rm -rf '${SF_MODS}/${ref}.nxnew'`);
          return { ok: false, error: `Couldn't download or unpack ${ref} ${v.version} on the server.` };
        }
      }
      await execRemote(conn, `chown -R --reference='${SF_ROOT}' '${SF_MODS}' 2>/dev/null; true`);
    } finally {
      await execRemote(conn, `rm -rf '${shq(tmp)}'`);
    }
    if (!(await restartGame(conn, "satisfactory", "satisfactory"))) {
      return { ok: false, error: "The mod was placed, but the server didn't restart — restart it from the dashboard to load it." };
    }
    return { ok: true, version: chosen.get(mainRef)?.version };
  });
}
EOF
