/**
 * Bulk-import the real Satisfactory mod catalogue from ficsit.app (the
 * Satisfactory Mod Repository — the same repository Satisfactory Mod Manager
 * uses) into `GameMod` (gameFamily "satisfactory", source "ficsit"). Part of
 * the 2026-09-30 family-coverage pass; same shape/safety rails as the other
 * importers here: dry-run by default, `--apply` to write,
 * scripts/db-target-guard.ts enforced, idempotent upsert matched on the real
 * immutable mod_reference.
 *
 * SOURCE: api.ficsit.app/v2/query — public, keyless GraphQL (checked live
 * 2026-09-30: `getMods` reports 1,584 mods). Metadata only: no mod file is
 * downloaded here; the customer's own server fetches the file at install time
 * (worker/game-mods.ts's satisfactorySync).
 *
 * WHAT IS IMPORTED — only what Nxeon's server can actually run: a mod is kept
 * only if its latest version (release, else beta, else alpha — the
 * repository's own `latestVersions`) ships a `LinuxServer` build target.
 * Nxeon's Satisfactory image is the Linux dedicated server; a Windows-only
 * or client-only mod could never load on it, so it isn't offered. Plus the
 * same downloads > 1000 floor the Modrinth/mod.io/ModDB importers use,
 * most-downloaded first, capped at --max (default 1000).
 *
 * FIELD NOTES — every value from the API, nothing invented:
 *   name / short_description / logo / downloads (real lifetime count) /
 *   authors[0].user.username; popularity = downloads (ficsit's own
 *   `popularity` field is a rank-like score, not a count); gameVersions =
 *   [latest version's game_version condition] (a real CL requirement such as
 *   ">=491125"); dependencyCount = its non-optional dependencies (SML
 *   included — SML is itself installed through the same path);
 *   url = https://ficsit.app/mod/<mod_reference>; category "Mod"; license null
 *   (the listing exposes none).
 *
 *   NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-ficsit-catalog.ts [--apply] [--max=1000] [--min-downloads=1000]
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("import-ficsit-catalog.ts");

import { db } from "../lib/db";

const FAMILY = "satisfactory";
const SOURCE = "ficsit";
const API = "https://api.ficsit.app/v2/query";
const PAGE = 100;

type Ver = { version: string; game_version?: string | null; targets?: { targetName: string }[]; dependencies?: { optional: boolean }[] } | null;
type ModRow = {
  name: string;
  mod_reference: string;
  short_description?: string | null;
  logo?: string | null;
  downloads?: number | null;
  hidden?: boolean | null;
  authors?: { user?: { username?: string } | null }[];
  latestVersions?: { release?: Ver; beta?: Ver; alpha?: Ver } | null;
};

function parseArgs(argv: string[]) {
  const get = (n: string) => argv.find((a) => a.startsWith(`--${n}=`))?.split("=")[1];
  return { apply: argv.includes("--apply"), max: Number(get("max") ?? 1000), minDownloads: Number(get("min-downloads") ?? 1000) };
}

async function page(offset: number): Promise<{ count: number; mods: ModRow[] }> {
  const verFields = "version game_version targets { targetName } dependencies { optional }";
  const query = `{ getMods(filter: { limit: ${PAGE}, offset: ${offset}, order_by: downloads, order: desc }) { count mods { name mod_reference short_description logo downloads hidden authors { user { username } } latestVersions { release { ${verFields} } beta { ${verFields} } alpha { ${verFields} } } } } }`;
  const res = await fetch(API, { method: "POST", headers: { "Content-Type": "application/json", "User-Agent": "Nxeon/1.0 (mods@nxeon.cloud)" }, body: JSON.stringify({ query }) });
  if (!res.ok) throw new Error(`ficsit getMods offset=${offset}: HTTP ${res.status}`);
  const body = (await res.json()) as { data?: { getMods?: { count: number; mods: ModRow[] } }; errors?: unknown };
  if (!body.data?.getMods) throw new Error(`ficsit getMods offset=${offset}: ${JSON.stringify(body.errors ?? body).slice(0, 300)}`);
  return body.data.getMods;
}

function slugify(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 70) || "mod";
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  console.log(`ficsit.app import — ${args.apply ? "APPLY" : "DRY RUN"} max=${args.max} minDownloads=${args.minDownloads}`);
  const existing = await db.gameMod.findMany({ where: { gameFamily: FAMILY }, select: { id: true, slug: true, source: true, sourceId: true } });
  const byRef = new Map(existing.filter((e) => e.source === SOURCE && e.sourceId).map((e) => [e.sourceId as string, e]));
  const used = new Set(existing.map((e) => e.slug));

  let offset = 0, kept = 0, created = 0, updated = 0, noLinux = 0, below = 0, failed = 0, total = 0;
  outer: for (;;) {
    const { count, mods } = await page(offset);
    total = count;
    if (!mods.length) break;
    for (const m of mods) {
      if (kept >= args.max) break outer;
      if ((m.downloads ?? 0) <= args.minDownloads) { below++; break outer; } // downloads-desc: everything after is below too
      if (m.hidden) continue;
      const latest = m.latestVersions?.release ?? m.latestVersions?.beta ?? m.latestVersions?.alpha ?? null;
      if (!latest || !(latest.targets ?? []).some((t) => t.targetName === "LinuxServer")) { noLinux++; continue; }
      kept++;
      const prior = byRef.get(m.mod_reference);
      let slug = prior?.slug;
      if (!slug) {
        const base = slugify(m.mod_reference);
        slug = base;
        for (let i = 2; used.has(slug); i++) slug = `${base}-${i}`;
        used.add(slug);
      }
      const data = {
        name: m.name,
        category: "Mod",
        description: m.short_description?.trim() || null,
        iconUrl: m.logo || null,
        url: `https://ficsit.app/mod/${m.mod_reference}`,
        popularity: m.downloads ?? 0,
        downloads: m.downloads ?? null,
        gameVersions: latest.game_version ? [latest.game_version] : [],
        dependencyCount: (latest.dependencies ?? []).filter((d) => !d.optional).length,
        authorName: m.authors?.[0]?.user?.username ?? null,
        license: null,
        serverSide: "required",
        source: SOURCE,
        sourceId: m.mod_reference,
        active: true,
        verifiedAt: new Date(),
        upstreamOk: true,
        upstreamNote: null,
      };
      if (!args.apply) {
        if (kept <= 5) console.log(`  [dry] ${m.mod_reference} "${m.name}" downloads=${m.downloads} game=${latest.game_version} slug=${slug}`);
        continue;
      }
      try {
        if (prior) {
          await db.gameMod.update({ where: { id: prior.id }, data, select: { id: true } });
          updated++;
        } else {
          await db.gameMod.create({ data: { gameFamily: FAMILY, slug, ...data }, select: { id: true } });
          created++;
        }
      } catch (e) {
        failed++;
        console.error(`  [db] ${m.mod_reference}: ${e instanceof Error ? e.message : e}`);
      }
    }
    offset += PAGE;
    if (offset >= total) break;
    await new Promise((r) => setTimeout(r, 500));
  }
  console.log(`\nDONE (${args.apply ? "APPLIED" : "DRY RUN — nothing written"}): repository total=${total} kept=${kept} created=${created} updated=${updated} skippedNoLinuxServer=${noLinux} stoppedAtFloor=${below > 0} failed=${failed}`);
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

