p='worker/game-mods.ts'
s=open(p).read()
a=s.index('// --- Garry\'s Mod — Steam Workshop addons, placed as .gma')
b=s.index('// --- Necesse — Steam Workshop mods')
new='''// --- Garry's Mod — Steam Workshop addons, extracted into garrysmod/addons ---
//
// ghcr.io/ich777/steamcmd:garrysmod (github.com/ich777/docker-steamcmd-server,
// `garrysmod` branch): serverfiles at /serverdata/serverfiles (= host
// /opt/gmod), steamcmd at /serverdata/steamcmd/steamcmd.sh (inside the
// container only), server runs as user `steam`.
//
// VERIFIED LIVE 2026-09-30 on a real test server — including one wrong turn
// worth recording: a dedicated server does NOT mount a packed `.gma` dropped
// into garrysmod/addons (ULib/ULX placed that way never ran — no data/ulib or
// data/ulx appeared). Each addon is therefore unpacked with gmad_linux —
// Facepunch's own addon tool, which ships in the server install at
// bin/gmad_linux — into its own addons/nxw-<id>/ folder, the "legacy addon"
// layout the server does load. `resource.AddWorkshop` (Garry's Mod's
// documented API) then makes joining clients fetch the same addon from Steam.
// `+host_workshop_collection` was considered and rejected: it only takes a
// COLLECTION id, and the catalogue is individual addons.
const GMOD_ROOT = "/opt/gmod/garrysmod";
const GMOD_HOST = "/opt/gmod";
const GMOD_CONTAINER = "/serverdata/serverfiles";

async function applyGmodWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
  const wanted = ids.filter(isWorkshopId);
  return withSftp(server, async (conn, sftp) => {
    const root = await execRemote(conn, `[ -d '${GMOD_ROOT}' ] && [ -x '${GMOD_HOST}/bin/gmad_linux' ] && echo YES`);
    if (root.stdout.trim() !== "YES") return { ok: false, error: "Couldn't find this server's garrysmod folder — is the server fully set up?" };
    await execRemote(conn, `mkdir -p '${GMOD_ROOT}/addons' '${GMOD_ROOT}/lua/autorun/server'`);
    for (const id of wanted) {
      const have = await execRemote(conn, `[ -d '${GMOD_ROOT}/addons/nxw-${id}' ] && [ -n "$(ls -A '${GMOD_ROOT}/addons/nxw-${id}')" ] && echo YES`);
      if (have.stdout.trim() === "YES") continue;
      const got = await fetchWorkshopItem(conn, {
        container: "gmod",
        user: "steam",
        steamcmd: "/serverdata/steamcmd/steamcmd.sh",
        appid: WORKSHOP_APPID.gmod,
        id,
        stageInContainer: `${GMOD_CONTAINER}/.nxw-workshop`,
        stageOnHost: `${GMOD_HOST}/.nxw-workshop`,
      });
      if ("error" in got) return { ok: false, error: got.error };
      // Current uploads arrive as a plain .gma; older ones as an
      // LZMA-compressed `*_legacy.bin` of the same .gma — unpack that with xz.
      const gma = `${GMOD_HOST}/.nxw-workshop/nxw-${id}.gma`;
      const prep = await execRemote(
        conn,
        `d='${shq(got.hostPath)}'; out='${gma}'; ` +
          `g=$(find "$d" -maxdepth 2 -type f -iname '*.gma' | head -1); b=$(find "$d" -maxdepth 2 -type f -iname '*.bin' | head -1); ` +
          `if [ -n "$g" ]; then cp -f "$g" "$out"; elif [ -n "$b" ]; then xz --format=lzma -dc "$b" > "$out" || rm -f "$out"; fi; ` +
          `[ -s "$out" ] && head -c 4 "$out" | grep -q GMAD && chmod 666 "$out" && echo NXOK || echo NXBAD`
      );
      if (!/NXOK/.test(prep.stdout)) return { ok: false, error: `Steam Workshop item ${id} downloaded, but it isn't a Garry's Mod addon file.` };
      const dest = `${GMOD_ROOT}/addons/nxw-${id}`;
      const extract = await execRemote(
        conn,
        `rm -rf '${dest}'; docker exec -u steam gmod ${GMOD_CONTAINER}/bin/gmad_linux extract ` +
          `-file '${GMOD_CONTAINER}/.nxw-workshop/nxw-${id}.gma' -out '${GMOD_CONTAINER}/garrysmod/addons/nxw-${id}' >/dev/null 2>&1; ` +
          `[ -d '${dest}' ] && [ -n "$(ls -A '${dest}')" ] && echo NXOK || { rm -rf '${dest}'; echo NXBAD; }`
      );
      if (!/NXOK/.test(extract.stdout)) return { ok: false, error: `Couldn't unpack Steam Workshop addon ${id} on the server.` };
    }
    // Drop addons that are no longer wanted (and any packed .gma an earlier
    // build of this installer may have left behind).
    const present = await execRemote(conn, `ls '${GMOD_ROOT}/addons/' 2>/dev/null | sed -n 's/^nxw-\\\\([0-9]*\\\\)\\\\(\\\\.gma\\\\)\\\\{0,1\\\\}$/\\\\1/p' | sort -u`);
    for (const id of present.stdout.split(/\\r?\\n/).map((x) => x.trim()).filter(Boolean)) {
      if (!wanted.includes(id)) await execRemote(conn, `rm -rf '${GMOD_ROOT}/addons/nxw-${id}' '${GMOD_ROOT}/addons/nxw-${id}.gma'`);
    }
    await execRemote(conn, `rm -f '${GMOD_ROOT}'/addons/nxw-*.gma`);
    await sftpWrite(sftp, `${GMOD_ROOT}/lua/autorun/server/nxeon_workshop.lua`, gmodWorkshopLua(wanted));
    await execRemote(conn, `rm -rf '${GMOD_HOST}/.nxw-workshop'; chown -R --reference='${GMOD_ROOT}' '${GMOD_ROOT}/addons' '${GMOD_ROOT}/lua/autorun/server' 2>/dev/null; true`);
    if (!(await restartGame(conn, "gmod", "gmod"))) {
      return { ok: false, error: "The addon was placed, but the server didn't restart — restart it from the dashboard to load it." };
    }
    return { ok: true };
  });
}

'''
