      const dest = `${GMOD_ROOT}/addons/nxw-${id}`;
      const extract = await execRemote(
        conn,
        `rm -rf '${dest}'; docker exec -u steam gmod ${GMOD_CONTAINER}/bin/gmad_linux extract ` +
          `-file '${GMOD_CONTAINER}/.nxw-workshop/nxw-${id}.gma' -out '${GMOD_CONTAINER}/garrysmod/addons/nxw-${id}' >/dev/null 2>&1; ` +
          `[ -d '${dest}' ] && [ -n "$(ls -A '${dest}')" ] && echo NXOK || { rm -rf '${dest}'; echo NXBAD; }`
      );
      if (!/NXOK/.test(extract.stdout)) return { ok: false, error: `Couldn't unpack Steam Workshop addon ${id} on the server.` };
    }
    // Drop addons that are no longer wanted (and any packed .gma an earlier
    // build of this installer may have left behind).
    const present = await execRemote(conn, `ls '${GMOD_ROOT}/addons/' 2>/dev/null | sed -n 's/^nxw-\\\\([0-9]*\\\\)\\\\(\\\\.gma\\\\)\\\\{0,1\\\\}$/\\\\1/p' | sort -u`);
    for (const id of present.stdout.split(/\\r?\\n/).map((x) => x.trim()).filter(Boolean)) {
      if (!wanted.includes(id)) await execRemote(conn, `rm -rf '${GMOD_ROOT}/addons/nxw-${id}' '${GMOD_ROOT}/addons/nxw-${id}.gma'`);
    }
    await execRemote(conn, `rm -f '${GMOD_ROOT}'/addons/nxw-*.gma`);
    await sftpWrite(sftp, `${GMOD_ROOT}/lua/autorun/server/nxeon_workshop.lua`, gmodWorkshopLua(wanted));
