// Killing Floor 2 — LinuxServer-KFEngine.ini Workshop subscriptions
// ---------------------------------------------------------------------------

/** rouhim/killing-floor-2-server's own env var for the same ini key. NOT used
 *  to install: verified live 2026-09-30 that its envini step only ever ADDS
 *  `ServerSubscribedWorkshopItems=` lines (a removed id stayed subscribed and
 *  a kept one was duplicated after a recreate), so removal can't work through
 *  it. The installer edits the ini directly instead and makes sure this var
 *  is unset so the image can't re-add stale ids. */
export const KF2_WORKSHOP_ENV = "KF2_SERVER_SUBSCRIBED_WORKSHOP_ITEMS";

const KF2_WS_SECTION = "[OnlineSubsystemSteamworks.KFWorkshopSteamworks]";
const KF2_NET_SECTION = "[IpDrv.TcpNetDriver]";
const KF2_WS_DOWNLOAD = "DownloadManagers=OnlineSubsystemSteamworks.SteamWorkshopDownload";

/**
 * Rewrite a KF2 `LinuxServer-KFEngine.ini` so its Workshop subscription list
 * is EXACTLY `ids` — one `ServerSubscribedWorkshopItems=<id>` line each under
 * `[OnlineSubsystemSteamworks.KFWorkshopSteamworks]` (Tripwire's documented
 * dedicated-server Workshop mechanism; the server downloads each item itself
 * on boot) — and, when there is anything subscribed, so `[IpDrv.TcpNetDriver]`
 * offers the Workshop download manager first, which is what lets joining
 * players' clients fetch the same items. Every other line is left alone.
 */
export function updateKf2Ini(content: string, ids: string[]): string {
  const clean = [...new Set(ids.filter((id) => /^\\d{1,20}$/.test(id)))];
  let lines = content.split(/\\r?\\n/).filter(
    (l) => !/^\\s*ServerSubscribedWorkshopItems\\s*=/i.test(l) && l.trim() !== KF2_WS_DOWNLOAD
  );
  const insertAfterHeader = (header: string, add: string[]) => {
    const i = lines.findIndex((l) => l.trim().toLowerCase() === header.toLowerCase());
    if (i >= 0) lines.splice(i + 1, 0, ...add);
    else {
      while (lines.length && lines[lines.length - 1].trim() === "") lines.pop();
      lines.push("", header, ...add);
    }
  };
  if (clean.length) {
    insertAfterHeader(KF2_WS_SECTION, clean.map((id) => `ServerSubscribedWorkshopItems=${id}`));
    insertAfterHeader(KF2_NET_SECTION, [KF2_WS_DOWNLOAD]);
  }
  const out = lines.join("\\n");
  return out.endsWith("\\n") ? out : out + "\\n";
}

