b=s.index('/** Update `Key=Value` lines in a PZ-style ini')
new='''/** Unturned — `WorkshopDownloadConfig.json` (`File_IDs: [...]`), confirmed
 *  against Smartly Dressed Games' own official server-hosting docs. Written
 *  straight to disk, no container recreate needed — the dedicated server
 *  reads this file on ITS OWN next start and downloads each id itself.
 *
 *  FIXED 2026-09-30 (live-verified on a real container of the production
 *  image) — this used to write a hardcoded `/opt/unturned/Servers/nxeon`,
 *  which was only right for fragsoc/unturned (prisma/seed-wave2-games.ts:
 *  `-v /opt/unturned:/config -e SERVER_ID=nxeon`). Production's live
 *  `unturned` OsTemplate has run imperialplugins/unturned since Wave 7:
 *  `-v /opt/unturned:/home/steam/Unturned/Servers -e SERVER_NAME='Nxeon Unturned'`
 *  — so the host folder IS the game's Servers/ directory, and the old path
 *  (Servers/Servers/nxeon from the game's side) was never read: every Unturned
 *  Workshop install reported INSTALLED while the server ignored it. The real
 *  folder isn't even derivable from the env var: the image launches
 *  `+secureserver/"$SERVER_NAME"`, and a live server named "Nxeon Unturned"
 *  created `/opt/unturned/Nxeon Unturned"` — with a trailing double quote,
 *  from the engine's own command-line quoting. So the folder is DISCOVERED:
 *  the one under the mount that the server itself populated (it writes its
 *  own WorkshopDownloadConfig.json + Server/ on first boot). No such folder
 *  yet means the server has never started, and nothing is written — a guessed
 *  path is exactly how the old bug reported success for nothing. The file is
 *  read-modify-written so the server's own other settings survive. */
async function unturnedServerDir(conn: Client): Promise<string | null> {
  const r = await execRemote(
    conn,
    `for m in /opt/unturned /opt/unturned/Servers; do [ -d "$m" ] || continue; ` +
      `for d in "$m"/*/; do [ -f "$d/WorkshopDownloadConfig.json" ] && [ -d "$d/Server" ] && printf '%s\\\\0' "\${d%/}"; done; done`
  );
  const dirs = r.stdout.split("\\0").map((x) => x.trim()).filter(Boolean);
  if (dirs.length === 0) return null;
  if (dirs.length === 1) return dirs[0];
  const env = await readEnvMap(conn, "unturned");
  const name = env?.get("SERVER_NAME") ?? env?.get("SERVER_ID") ?? "";
  const byName = dirs.filter((d) => name && d.split("/").pop()!.startsWith(name));
  return byName.length === 1 ? byName[0] : null;
}

async function applyUnturnedWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
  return withSftp(server, async (conn, sftp) => {
    const dir = await unturnedServerDir(conn);
    if (!dir) {
      return { ok: false, error: "This Unturned server hasn't created its own folder yet — start it once, then try again." };
    }
    const path = `${dir}/WorkshopDownloadConfig.json`;
    const existing = await sftpRead(sftp, path);
    let cfg: Record<string, unknown> = {};
    try {
      cfg = existing ? (JSON.parse(existing) as Record<string, unknown>) : {};
    } catch {
      return { ok: false, error: "This server's WorkshopDownloadConfig.json isn't valid JSON — nothing was changed." };
    }
    cfg.File_IDs = ids.filter(isWorkshopId).map((id) => Number(id));
    await sftpWrite(sftp, path, JSON.stringify(cfg, null, 2) + "\\n");
    // SFTP writes as root; the game runs as the image's own `steam` user and
    // re-serializes this file on boot, so keep it owned like its folder.
    await execRemote(conn, `chown --reference='${shq(dir)}' '${shq(path)}' 2>/dev/null; true`);
    return { ok: true };
  });
}

'''
